const body = $input.first().json.body || {};
const category = String(body.category || 'معلومات عامة');
const count = Math.min(Math.max(Number(body.count) || 10, 1), 20);
const now = new Date();
const kwHour = (now.getUTCHours() + 3) % 24;
const autoShift = (kwHour >= 8 && kwHour < 20) ? 'A' : 'B';
const shift = String(body.shift || autoShift).toUpperCase() === 'B' ? 'B' : 'A';
const cells = Array.from({ length: 10 }, (_, i) => ({
  cell_id: 'cell_' + String(i + 1).padStart(2, '0'),
  shift: i % 2 === 0 ? 'A' : 'B'
}));
const active = cells.filter(c => c.shift === shift);
let cell = body.cell_id ? cells.find(c => c.cell_id === body.cell_id) : active[Math.floor(Math.random() * active.length)];
if (!cell) cell = active[0];
return [{ json: {
  category, count, shift,
  cell_id: cell.cell_id,
  on_shift: cell.shift === shift,
  active_cells: active.map(c => c.cell_id),
  resting_cells: cells.filter(c => c.shift !== shift).map(c => c.cell_id),
  started_at: now.toISOString()
} }];

