const raw = String($input.first().json.output || '[]');
const match = raw.match(/\[[\s\S]*\]/);
let list = [];
try { list = JSON.parse(match ? match[0] : raw); } catch (e) { list = []; }
const allowed = ['nasa', 'wikimedia', 'unsplash', 'pexels'];
return list.map((q, i) => ({ json: {
  q_index: i + 1,
  question: q.question,
  answer: q.answer,
  difficulty: q.difficulty || 'medium',
  image_query: q.image_query || q.question,
  image_source: allowed.includes(q.image_source) ? q.image_source : 'pexels',
  sources_hint: q.sources_hint || []
} }));

const items = $input.all();
const out = items.map((it, i) => {
  let q = {};
  try { q = $('Parse Questions').itemMatching(i).json; } catch (e) { q = {}; }
  const r = it.json || {};
  let url = null, source = q.image_source || 'unknown', credit = '';
  if (r.collection && r.collection.items && r.collection.items.length) {
    const x = r.collection.items[0];
    url = x.links && x.links[0] ? x.links[0].href : null; source = 'nasa'; credit = 'NASA';
  } else if (r.query && r.query.pages) {
    const p = Object.values(r.query.pages)[0] || {};
    const info = (p.imageinfo || [])[0] || {};
    url = info.url || null; source = 'wikimedia'; credit = info.user || 'Wikimedia Commons';
  } else if (r.results && r.results.length) {
    url = r.results[0].urls.regular; source = 'unsplash'; credit = (r.results[0].user || {}).name || 'Unsplash';
  } else if (r.photos && r.photos.length) {
    url = r.photos[0].src.large; source = 'pexels'; credit = r.photos[0].photographer || 'Pexels';
  }
  const idx = q.q_index || i + 1;
  return { ...q, image: { file_name: 'img_' + String(idx).padStart(4, '0') + '.jpg', url, source, credit, found: !!url } };
});
out.sort((a, b) => (a.q_index || 0) - (b.q_index || 0));
const found = out.filter(o => o.image.found).length;
return [{ json: { questions: out, image_hit_rate: out.length ? found / out.length : 0 } }];

