const TRUSTED = ['fifa', 'kooora', 'imdb', 'tmdb', 'themoviedb', 'britannica', 'nasa', 'uefa', 'the-afc', 'afc', 'bbc', 'reuters', 'nationalgeographic', 'national geographic', 'olympics'];
const raw = String($input.first().json.output || '[]');
const m = raw.match(/\[[\s\S]*\]/);
let verdicts = [];
try { verdicts = JSON.parse(m ? m[0] : raw); } catch (e) { verdicts = []; }
const byIdx = {};
verdicts.forEach(v => { byIdx[v.q_index] = v; });
const questions = $('3. Rename img_XXXX').first().json.questions;
const approved = [], rejected = [];
for (const q of questions) {
  const v = byIdx[q.q_index] || { verdict: 'rejected', sources: [] };
  const trusted = (v.sources || []).filter(s => {
    const t = (String(s.name || '') + ' ' + String(s.url || '')).toLowerCase();
    return !t.includes('wikipedia') && TRUSTED.some(d => t.includes(d));
  });
  const ok = v.verdict !== 'rejected' && trusted.length >= 2;
  const final = { ...q, answer: v.verdict === 'fixed' && v.corrected_answer ? v.corrected_answer : q.answer, verdict: ok ? v.verdict : 'rejected', sources: trusted };
  (ok ? approved : rejected).push(final);
}
return [{ json: { approved, rejected, total: questions.length, image_hit_rate: $('3. Rename img_XXXX').first().json.image_hit_rate } }];

