const s = $('Shift Scheduler').first().json;
const f = $('Enforce 2 Trusted Sources').first().json;
const raw = String($input.first().json.output || '{}');
const m = raw.match(/\{[\s\S]*\}/);
let review = {};
try { review = JSON.parse(m ? m[0] : raw); } catch (e) { review = { score: 0, fixes: ['تعذر قراءة تقييم المراقب'] }; }
const score = Number(review.score) || 0;
const ready = {
  cell_id: s.cell_id, shift: s.shift, category: s.category,
  score, status: score >= 7 && f.approved.length > 0 ? 'ready' : 'needs_rework',
  review, questions: f.approved, rejected_count: f.rejected.length,
  generated_at: new Date().toISOString()
};
const text = JSON.stringify(ready, null, 2);
return [{ json: ready, binary: { data: { data: Buffer.from(text).toString('base64'), mimeType: 'application/json', fileName: 'ready.json' } } }];
